#nullable enable // autogenerated

using System;
using MVZ2Logic.Saves;
using PVZEngine;

namespace MVZ2.Vanilla.Saves
{
    public class VanillaSaveData : LogicSaveData
    {
        public VanillaSaveData(string spaceName) : base(spaceName)
        {
        }
        protected override SerializableModSaveData CreateSerializable()
        {
            return new SerializableVanillaSaveData();
        }
        protected override void WriteToSerializable(SerializableModSaveData serializable)
        {
            base.WriteToSerializable(serializable);
            if (serializable is not SerializableVanillaSaveData logicSeri)
                return;
            logicSeri.teleporterTeam = TeleporterTeam?.ToSerializable();
        }
        protected override void LoadFromSerializable(SerializableModSaveData serializable)
        {
            base.LoadFromSerializable(serializable);
            if (serializable is not SerializableVanillaSaveData logicSeri)
                return;
            TeleporterTeam = logicSeri.teleporterTeam != null ? Saves.TeleporterTeam.FromSerializable(logicSeri.teleporterTeam) : null;
        }
        public static VanillaSaveData DeserializeFrom(SerializableVanillaSaveData seri)
        {
            if (string.IsNullOrEmpty(seri.spaceName))
            {
                throw MissingSerializeDataException.Property<SerializableVanillaSaveData>(nameof(seri.spaceName));
            }
            var saveData = new VanillaSaveData(seri.spaceName);
            saveData.LoadFromSerializable(seri);
            return saveData;
        }
        public TeleporterTeam? TeleporterTeam { get; set; }
    }
    [Serializable]
    public class SerializableVanillaSaveData : SerializableLogicSaveData
    {
        public SerializableTeleporterTeam? teleporterTeam;
    }
}
